+  display: flex;
+  align-items: center;
+  gap: 10px;
+}
+
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 10px;
+  border-radius: 14px;
+  padding: 11px 14px;
+  text-decoration: none;
+  font-size: 13px;
+  letter-spacing: 0.25px;
+  border: 1px solid transparent;
+  cursor: pointer;
+  transition:
+    transform 160ms ease,
+    box-shadow 160ms ease,
+    background 160ms ease,
+    border-color 160ms ease;
+}
+
+.btn:focus-visible {
+  outline: 2px solid rgba(0, 180, 216, 0.65);
+  outline-offset: 2px;
+}
+
+.btn--primary {
+  background: linear-gradient(135deg, var(--accent), var(--accent2));
+  color: #05111f;
+  font-weight: 650;
+  box-shadow: 0 10px 26px rgba(0, 180, 216, 0.22);
+}
+
+.btn--primary:hover {
+  transform: translateY(-1px);
+  box-shadow: 0 16px 34px rgba(0, 180, 216, 0.28);
+}
+
+.btn--ghost {
+  border-color: rgba(148, 191, 255, 0.2);
+  background: rgba(148, 191, 255, 0.06);
+  color: var(--ink);
+}
+
+.btn--ghost:hover {
+  border-color: rgba(0, 180, 216, 0.35);
+  background: rgba(0, 180, 216, 0.08);
+  transform: translateY(-1px);
+}
+
+.btn--full {
+  width: 100%;
+}
+
+.hamburger {
+  display: none;
+  width: 42px;
+  height: 42px;
+  border-radius: 14px;
+  background: rgba(148, 191, 255, 0.06);
+  border: 1px solid rgba(148, 191, 255, 0.18);
+}
+
+.hamburger span {
+  display: block;
+  height: 2px;
+  width: 18px;
+  margin: 0 auto;
+  background: rgba(234, 242, 255, 0.75);
+  border-radius: 2px;
+}
+
+.hamburger span + span {
+  margin-top: 5px;
+}
+
+.mobile-drawer {
+  border-top: 1px solid var(--line);
+  background: rgba(11, 20, 32, 0.86);
+  backdrop-filter: blur(12px);
+}
+
+.mobile-drawer__inner {
+  width: min(1160px, calc(100% - 40px));
+  margin: 0 auto;
+  padding: 14px 0 18px;
+  display: grid;
+  gap: 12px;
+}
+
+.mobile-drawer.is-open {
+  animation: drawerIn 220ms ease both;
+}
+
+@keyframes drawerIn {
+  from {
+    opacity: 0;
+    transform: translateY(-8px);
+  }
+  to {
+    opacity: 1;
+    transform: translateY(0);
+  }
+}
+
+.mobile-drawer__section {
+  padding: 12px;
+  border: 1px solid rgba(148, 191, 255, 0.16);
+  border-radius: 16px;
+  background: rgba(148, 191, 255, 0.04);
+}
+
+.mobile-drawer__title {
+  font-size: 12px;
+  color: var(--ink3);
+  text-transform: uppercase;
+  letter-spacing: 0.7px;
+  margin-bottom: 6px;
+}
+
+.mobile-drawer__link {
+  display: block;
+  padding: 10px 10px;
+  border-radius: 12px;
+  text-decoration: none;
+  color: var(--ink2);
+}
+
+.mobile-drawer__link:hover {
+  background: rgba(0, 180, 216, 0.1);
+  color: var(--ink);
+}
+
+.mobile-drawer__cta {
+  background: rgba(0, 180, 216, 0.06);
+}
+
+.section {
+  padding: 84px 0;
+}
+
+.section--tight {
+  padding: 58px 0;
+}
+
+.kicker {
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+  font-size: 12px;
+  letter-spacing: 0.8px;
+  text-transform: uppercase;
+  color: rgba(234, 242, 255, 0.68);
+}
+
+.kicker::before {
+  content: '';
+  width: 28px;
+  height: 1px;
+  background: linear-gradient(90deg, var(--accent), transparent);
+}
+
+.h1 {
+  font-size: 54px;
+  line-height: 1.02;
+  letter-spacing: -1.6px;
+  margin: 16px 0 12px;
+}
+
+.h2 {
+  font-size: 34px;
+  line-height: 1.1;
+  letter-spacing: -0.8px;
+  margin: 0 0 12px;
+}
+
+.lead {
+  color: var(--ink2);
+  font-size: 16px;
+  max-width: 70ch;
+}
+
+.hero {
+  padding: 86px 0 40px;
+  position: relative;
+}
+
+.hero__grid {
+  display: grid;
+  grid-template-columns: 1.2fr 0.8fr;
+  gap: 34px;
+  align-items: center;
+}
+
+.hero__panel {
+  border: 1px solid rgba(148, 191, 255, 0.18);
+  border-radius: var(--radius2);
+  background: linear-gradient(
+    180deg,
+    rgba(148, 191, 255, 0.08),
+    rgba(148, 191, 255, 0.02)
