+}
+
+.hero__panel::before {
+  content: '';
+  position: absolute;
+  inset: -1px;
+  background: radial-gradient(
+      600px 400px at 40% 10%,
+      rgba(0, 180, 216, 0.22),
+      transparent 60%
+    ),
+    radial-gradient(
+      520px 360px at 90% 60%,
+      rgba(108, 194, 74, 0.18),
+      transparent 62%
+    );
