+  pointer-events: none;
+}
+
+.hero__panelInner {
+  position: relative;
+  padding: 18px 18px 14px;
+}
+
+.hero__badge {
+  display: inline-flex;
+  gap: 10px;
+  align-items: center;
+  padding: 8px 10px;
+  border-radius: 999px;
+  border: 1px solid rgba(0, 180, 216, 0.3);
+  background: rgba(0, 180, 216, 0.08);
+  color: rgba(234, 242, 255, 0.82);
+  font-size: 12px;
+  letter-spacing: 0.55px;
+}
+
+.hero__badgeDot {
+  width: 8px;
+  height: 8px;
+  border-radius: 99px;
+  background: var(--accent);
+  box-shadow: 0 0 0 4px rgba(0, 180, 216, 0.15);
+}
+
+.hero__cta {
+  display: flex;
+  gap: 12px;
+  margin-top: 18px;
+  flex-wrap: wrap;
+}
+
+.hero__aside {
+  padding: 18px;
+}
+
+.hero__asideTitle {
+  font-size: 12px;
+  letter-spacing: 0.7px;
+  text-transform: uppercase;
+  color: rgba(234, 242, 255, 0.65);
+  margin-bottom: 10px;
+}
+
+.hero__metrics {
+  display: grid;
+  gap: 10px;
+}
+
+.metric {
+  border: 1px solid rgba(148, 191, 255, 0.18);
+  border-radius: 16px;
+  background: rgba(148, 191, 255, 0.05);
+  padding: 12px;
+}
+
+.metric__top {
+  display: flex;
+  align-items: baseline;
+  justify-content: space-between;
+  gap: 10px;
+}
+
+.metric__num {
+  font-size: 22px;
+  font-weight: 680;
+  letter-spacing: -0.5px;
+}
+
+.metric__label {
+  font-size: 12px;
+  color: rgba(234, 242, 255, 0.65);
+}
+
+.metric__bar {
+  height: 8px;
+  border-radius: 999px;
+  background: rgba(148, 191, 255, 0.1);
+  overflow: hidden;
+  margin-top: 10px;
+}
+
+.metric__bar > span {
+  display: block;
+  height: 100%;
+  width: 0;
+  background: linear-gradient(90deg, var(--accent), rgba(108, 194, 74, 0.9));
+  border-radius: 999px;
+  animation: growBar 1200ms ease forwards;
+}
+
+@keyframes growBar {
+  from {
+    width: 0;
+  }
+  to {
+    width: var(--w);
+  }
+}
+
+.card {
+  border: 1px solid rgba(148, 191, 255, 0.16);
+  border-radius: var(--radius);
+  background: rgba(148, 191, 255, 0.04);
+  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.25);
+}
+
