+  gap: 14px;
+  align-items: start;
+}
+
+.panelCard {
+  border: 1px solid rgba(148, 191, 255, 0.16);
+  border-radius: 18px;
+  background: rgba(148, 191, 255, 0.04);
+  padding: 14px;
