+.panelCard__title {
+  font-weight: 700;
+  letter-spacing: -0.2px;
+  margin-bottom: 6px;
+}
+
+.panelCard__desc {
+  color: var(--ink2);
+  font-size: 13px;
+}
+
+.diagram {
+  border: 1px solid rgba(148, 191, 255, 0.16);
+  border-radius: var(--radius2);
